import React, { useEffect, useState } from 'react';
import { getUserFromToken, clearToken } from '../utils/auth';
import { useNavigate } from 'react-router-dom';
import { get } from '../services/api';

export default function Dashboard() {
  const user = getUserFromToken();
  const navigate = useNavigate();

  const logout = () => {
    clearToken();
    navigate('/login');
  };

  const [purchases, setPurchases] = useState([]);
  const [codes, setCodes] = useState([]);

  useEffect(() => {
    fetchData();
  }, []);

  async function fetchData() {
    try {
      const p = await get('/purchases/my');
      setPurchases(p.purchases || []);
    } catch (e) {}

    try {
      const c = await get('/booking/my-code');
      if (c) {
        if (Array.isArray(c)) setCodes(c);
        else if (c.codes) setCodes(c.codes);
        else if (c.id) setCodes([c]);
        else setCodes([]);
      }
    } catch (e) {}
  }

  return (
    <div className="container">
      <h2>Dashboard</h2>
      {user ? (
        <div>
          <p>User ID: {user.id}</p>
          <button onClick={logout}>Logout</button>

          <h3>Your Purchases</h3>
          {purchases.length === 0 && <p>No purchases yet.</p>}
          {purchases.map(p => (
            <div key={p.id} className="card">Purchase {p.id} - {p.status}</div>
          ))}

          <h3>Your Booking Codes</h3>
          {codes.length === 0 && <p>No confirmed bookings yet.</p>}
          {codes.map(c => (
            <div key={c.id} className="card">{c.bookingCode?.matchName || 'Booking'} - Code: {c.code || c.bookingCode?.code}</div>
          ))}
        </div>
      ) : (
        <p>No user info available.</p>
      )}
    </div>
  );
}
